<?php declare(strict_types=1); /** @var Closure(mixed): string $escape */ ?>
<div class="actions"><div><span class="status">ADM</span><h1>Etiquetas</h1><p class="meta">Organize os contatos do CRM com marcadores de nome e cor.</p></div><a href="<?= $escape($basePath) ?>/tags/create">Nova etiqueta</a></div>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<div class="table-responsive"><table><thead><tr><th>Etiqueta</th><th>Cor</th><th>Situação</th><th></th></tr></thead><tbody><?php if($tags===[]):?><tr><td colspan="4">Nenhuma etiqueta cadastrada.</td></tr><?php endif;?><?php foreach($tags as $tag):?><tr><td><span class="tag-badge" style="--tag-color:<?= $escape($tag['color']) ?>"><?= $escape($tag['name']) ?></span></td><td><?= $escape($tag['color']) ?></td><td><?= (int)$tag['is_active']===1?'Ativa':'Inativa' ?></td><td><a href="<?= $escape($basePath) ?>/tags/<?= $escape($tag['id']) ?>/edit">Editar</a></td></tr><?php endforeach;?></tbody></table></div>
